}

static std::string runProgram(const std::string& exePath, const std::string& input) {
    std::string inFile = "/tmp/mock3_p2_in_" + std::to_string(getpid()) + ".txt";
    std::string outFile = "/tmp/mock3_p2_out_" + std::to_string(getpid()) + ".txt";
